from pathlib import Path
import hashlib

import numpy as np
import pytest

from optosky_raman.importer import parse_file, load_directory, SpectrumImportError


def write_csv(tmp_path, name='-1.353ing cv.csv', encoding='utf-8', rows=None):
    text = '\n'.join([
        'Data Generated by,Optosky Raman Microscope',
        '积分时间(ms),10000', '激光功率(mW),30', '平均次数,3',
        '扫描时间,2026-10-12 13:51:42', '', '额外信息,保留中文', '',
        'BaseLine Subtracted,dArK,RAMAN SHIFT,Raw,Dark Subtracted',
        *(rows or ['-2,10,200,20,10', '3,11,201,31,20', '4,12,202,42,30']),
        '',
    ])
    p = tmp_path / name
    p.write_bytes(text.encode(encoding))
    return p


@pytest.mark.parametrize('encoding', ['utf-8', 'gb18030', 'utf-16'])
def test_dynamic_header_encoding_channels_and_original_are_preserved(tmp_path, encoding):
    p = write_csv(tmp_path, encoding=encoding)
    before = p.read_bytes()
    r = parse_file(p, batch='experiment')
    np.testing.assert_array_equal(r.x, [200, 201, 202])
    np.testing.assert_array_equal(r.channels['baseline_subtracted'], [-2, 3, 4])
    assert r.metadata['integration_time_s'] == 10
    assert r.metadata['laser_power_mw'] == 30
    assert r.metadata['averages'] == 3
    assert r.acquired_at.isoformat() == '2026-10-12T13:51:42'
    assert '保留中文' in r.metadata['original_text']
    assert len(r.metadata['original_rows']) >= 12
    assert r.sha256 == hashlib.sha256(before).hexdigest()
    assert p.read_bytes() == before


@pytest.mark.parametrize('rows,reason', [
    (['1,1,200,2,1', '1,1,200,2,1'], 'duplicate'),
    (['1,1,200,2,1', '1,1,201,2,'], 'missing'),
    (['1,1,200,2,1', '1,1,201,2,nan'], 'non-finite'),
    (['1,1,200,2,1', '1,1,201,2,wrong'], 'non-numeric'),
    (['1,1,201,2,1', '1,1,200,2,1', '1,1,202,2,1'], 'monotonic'),
])
def test_invalid_numeric_rows_are_not_silently_removed(tmp_path, rows, reason):
    p = write_csv(tmp_path, rows=rows)
    with pytest.raises(SpectrumImportError, match=reason):
        parse_file(p)


def test_directory_returns_each_file_error_and_keeps_valid_records(tmp_path):
    write_csv(tmp_path, name='-1.2cv.csv')
    (tmp_path / 'broken.CSV').write_text('no table\n', encoding='utf-8')
    records, errors = load_directory(tmp_path)
    assert len(records) == len(errors) == 1
    assert errors[0]['file'].endswith('broken.CSV')
    assert 'header' in errors[0]['error'].lower()


def test_raw_dark_mismatch_is_explicit_qc_not_recalculation(tmp_path):
    p = write_csv(tmp_path, rows=['1,1,200,10,2', '2,1,201,20,3'])
    r = parse_file(p)
    assert r.metadata['raw_dark_equal'] is False
    assert r.metadata['raw_dark_max_abs_difference'] == 16
    np.testing.assert_array_equal(r.channels['dark_subtracted'], [2, 3])
    assert any('raw_dark_mismatch' in w for w in r.warnings)


def test_descending_axis_is_preserved_and_ramanspy_conversion_is_explicit(tmp_path):
    p = write_csv(tmp_path, rows=['1,1,202,2,1', '1,1,201,2,1', '1,1,200,2,1'])
    r = parse_file(p)
    np.testing.assert_array_equal(r.x, [202, 201, 200])
    spectrum = r.to_ramanspy()
    np.testing.assert_array_equal(spectrum.spectral_axis, [200, 201, 202])
    np.testing.assert_array_equal(r.x, [202, 201, 200])


def test_duplicate_filename_subdirectories_have_unique_ids(tmp_path):
    one = tmp_path / 'one'
    two = tmp_path / 'two'
    one.mkdir(); two.mkdir()
    write_csv(one, name='-1.2cv.csv'); write_csv(two, name='-1.2cv.csv')
    records, errors = load_directory(tmp_path, batch='same')
    assert not errors
    assert len({r.id for r in records}) == 2


def test_configured_geometry_is_retained_and_override_is_traceable(tmp_path):
    p = write_csv(tmp_path, name='1.023CV.csv')
    r = parse_file(p, config={'experiment': {'optical_path_id': 'cellA', 'measurement_position': 'spot2'},
                            'filename_overrides': {p.name: {'potential_v': -1.023, 'reason': 'operator confirmed'}}})
    assert r.potential_v == -1.023
    assert r.metadata['potential']['filename_potential_v'] == 1.023
    assert r.metadata['measurement_position'] == 'spot2'
    assert r.metadata['optical_path_id'] == 'cellA'
